  if (/今天|今日|昨天|昨日|前天/.test(session.date)) {
    const offset = /前天/.test(session.date) ? 2 : /昨天|昨日/.test(session.date) ? 1 : 0;
    return Date.UTC(current.year, current.month - 1, current.day - offset, hour - 8, minute);
  }
