const initialSpaces: Space[] = [{ name: PERSONAL, role: '拥有者', members: [{ name: '我', role: '拥有者', state: '已加入' }] }, { name: TEAM, role: '管理员', members: [{ name: '我', role: '管理员', state: '已加入' }, { name: '王宁', role: '成员', state: '已加入' }, { name: 'Alex', role: '成员', state: '已加入' }] }];
