    <div className="action-grid"><Button tone="secondary" icon="pencil-simple" onClick={() => navigate({ view: 'memory-edit', id: m.id })}>编辑</Button><Button tone="secondary" icon="bookmark-simple" onClick={() => change({ starred: !m.starred }, m.starred ? '已取消收藏' : '已收藏')}>{m.starred ? '取消收藏' : '收藏'}</Button></div>
